    "inlineSchema": "// This is your Prisma schema file,\n// learn more about it in the docs: https://pris.ly/d/prisma-schema\n\n// Get a free hosted Postgres database in seconds: `npx create-db`\n\ngenerator client {\n  provider = \"prisma-client\"\n  output   = \"../src/generated/prisma\"\n}\n\ndatasource db {\n  provider = \"postgresql\"\n}\n\nenum TriggerMoment {\n  LOGIN\n  LOGOUT\n  DURING\n  MANUAL\n}\n\nenum FrequencyUnit {\n  DAY\n  WEEK\n  MONTH\n}\n\nenum EvaluationAction {\n  SHOWN\n  SKIPPED\n  SUBMITTED\n}\n\nmodel System {\n  id          String   @id @default(uuid()) @db.Uuid\n  name        String\n  code        String   @unique\n  description String?\n  baseUrl     String?\n  active      Boolean  @default(true)\n  createdAt   DateTime @default(now())\n\n  integration   Integration?\n  configuration WidgetConfiguration?\n  evaluations   SatisfactionEvaluation[]\n  interactions  WidgetInteraction[]\n}\n\nmodel Integration {\n  id             String   @id @default(uuid()) @db.Uuid\n  systemId       String   @unique @db.Uuid\n  apiKeyHash     String   @unique\n  allowedOrigins String[] @default([])\n  active         Boolean  @default(true)\n  createdAt      DateTime @default(now())\n\n  system System @relation(fields: [systemId], references: [id], onDelete: Cascade)\n}\n\nmodel Student {\n  id                String   @id @default(uuid()) @db.Uuid\n  institutionalCode String   @unique\n  fullName          String?\n  email             String?\n  active            Boolean  @default(true)\n  createdAt         DateTime @default(now())\n\n  evaluations  SatisfactionEvaluation[]\n  interactions WidgetInteraction[]\n}\n\nmodel WidgetConfiguration {\n  id                 String          @id @default(uuid()) @db.Uuid\n  systemId           String          @unique @db.Uuid\n  triggerMoments     TriggerMoment[] @default([LOGIN])\n  frequencyValue     Int             @default(1)\n  frequencyUnit      FrequencyUnit   @default(MONTH)\n  promptDelayMinutes Int             @default(0)\n  allowSkip          Boolean         @default(true)\n  active             Boolean         @default(true)\n  createdAt          DateTime        @default(now())\n  updatedAt          DateTime        @updatedAt\n\n  system System @relation(fields: [systemId], references: [id], onDelete: Cascade)\n}\n\nmodel SatisfactionEvaluation {\n  id              String    @id @default(uuid()) @db.Uuid\n  studentId       String    @db.Uuid\n  systemId        String    @db.Uuid\n  rating          Int?\n  comment         String?\n  lastEvaluatedAt DateTime?\n  nextEligibleAt  DateTime?\n  createdAt       DateTime  @default(now())\n  updatedAt       DateTime  @updatedAt\n\n  student Student @relation(fields: [studentId], references: [id])\n  system  System  @relation(fields: [systemId], references: [id])\n\n  history EvaluationHistory[]\n\n  @@unique([studentId, systemId])\n}\n\nmodel EvaluationHistory {\n  id           String   @id @default(uuid()) @db.Uuid\n  evaluationId String   @db.Uuid\n  rating       Int\n  comment      String?\n  answeredAt   DateTime @default(now())\n\n  evaluation SatisfactionEvaluation @relation(fields: [evaluationId], references: [id], onDelete: Cascade)\n}\n\nmodel WidgetInteraction {\n  id         String           @id @default(uuid()) @db.Uuid\n  studentId  String           @db.Uuid\n  systemId   String           @db.Uuid\n  sessionId  String?\n  action     EvaluationAction\n  occurredAt DateTime         @default(now())\n\n  student Student @relation(fields: [studentId], references: [id])\n  system  System  @relation(fields: [systemId], references: [id])\n\n  @@index([studentId, systemId, occurredAt])\n}\n\nmodel Role {\n  id          String   @id @default(uuid()) @db.Uuid\n  name        String   @unique\n  description String?\n  createdAt   DateTime @default(now())\n\n  administrators AdminUser[]\n}\n\nmodel AdminUser {\n  id           String   @id @default(uuid()) @db.Uuid\n  fullName     String\n  email        String   @unique\n  passwordHash String\n  active       Boolean  @default(true)\n  roleId       String   @db.Uuid\n  createdAt    DateTime @default(now())\n  updatedAt    DateTime @updatedAt\n\n  role Role @relation(fields: [roleId], references: [id])\n\n  auditLogs AuditLog[]\n}\n\nmodel AuditLog {\n  id          String   @id @default(uuid()) @db.Uuid\n  adminId     String?  @db.Uuid\n  action      String\n  entity      String\n  entityId    String?\n  description String?\n  metadata    Json?\n  createdAt   DateTime @default(now())\n\n  admin AdminUser? @relation(fields: [adminId], references: [id], onDelete: SetNull)\n\n  @@index([adminId, createdAt])\n}\n",
